const input = $input.first().json;
const topics = JSON.parse(input.topics);
const topic = topics[Math.floor(Math.random() * topics.length)];

return [{
  json: {
    board_id: input.board_id,
    topic,
    image_prompt: `${topic}, ${input.image_style}`
  }
}];

let raw = $json.message?.content ?? $json.content ?? $json.text;
if (Array.isArray(raw)) raw = raw[0]?.text ?? '';
raw = String(raw).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let caption;
try {
  caption = JSON.parse(raw);
} catch (e) {
  throw new Error('Could not parse caption JSON from OpenAI response: ' + raw);
}

const imageItem = $('Optimize Image').first();
const binaryData = imageItem.binary && (imageItem.binary.data || Object.values(imageItem.binary)[0]);
if (!binaryData) {
  throw new Error('No binary image data found on "Optimize Image" node output.');
}

const description = `${caption.description} ${caption.hashtags.map(h => '#' + h).join(' ')}`.slice(0, 500);

return [{
  json: {
    board_id: $('Pick Topic').first().json.board_id,
    title: String(caption.title).slice(0, 100),
    description,
    alt_text: caption.alt_text,
    image_base64: binaryData.data,
    content_type: binaryData.mimeType || 'image/jpeg'
  }
}];
